async function applyFavoriteHistory(change,useAfter){const starred=useAfter?change.after:change.before,at=useAfter?change.afterAt:change.beforeAt;if(change.entry.storage==='cloud')try{await writeCloudFavorite(change.entry,starred)}catch(error){console.error('[favorite] 撤销/重做收藏失败',error);toast('收藏状态同步失败：'+describeFavoriteRequestError(error));return false}setFavoriteMemory(change.entry,starred,at);renderLibrary();refreshEditorSidebar();syncCanvasFavoriteButton();return true}
function undoFavoriteChange(){if(!favoriteUndo.length)return false;const change=favoriteUndo.pop();void applyFavoriteHistory(change,false).then(ok=>{if(ok)favoriteRedo.push(change);else favoriteUndo.push(change)});return true}
