const VERSION_HISTORY_KEY='shinian-map-versions-v1',MAX_MAP_VERSIONS=20;let selectedVersionId=null;
function versionHistoryKey(target){return`local:${target.id}`}
function readLocalVersionHistory(){try{const value=JSON.parse(localStorage.getItem(VERSION_HISTORY_KEY)||'{}');return value&&typeof value==='object'?value:{}}catch(error){console.warn('[versions] 本地历史读取失败',error);return{}}}
function snapshotTimestamp(){return new Date().toISOString()}
function defaultVersionName(date=new Date()){return`手动保存 · ${new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(date)}`}
function isCloudVersionTarget(target){return!!target?.cloudOwnerId}
function assertVersionCloudAccess(target){if(!cloud||!ownerId||target.cloudOwnerId!==ownerId)throw new Error('请登录该云端脑图所属账号后管理版本历史')}
async function createVersionSnapshot(target,name=defaultVersionName(),{silent=false}={}){
 if(!target)throw new Error('没有正在打开的脑图');
 const savedAt=snapshotTimestamp(),snapshotData=JSON.parse(JSON.stringify(target)),snapshot={id:crypto.randomUUID(),versionName:name,createdAt:savedAt,snapshotData,thumbnail:typeof target.thumbnail==='string'?target.thumbnail:null};
 if(isCloudVersionTarget(target)){
  assertVersionCloudAccess(target);
  const row={mindmap_id:target.id,owner_id:target.cloudOwnerId,version_name:name,created_at:savedAt,snapshot_data:snapshotData,thumbnail:snapshot.thumbnail};
  const{data:inserted,error}=await cloud.from('mindmap_versions').insert(row).select('id,version_name,created_at,snapshot_data,thumbnail').single();
  if(error)throw error;
  snapshot.id=inserted.id;await pruneCloudVersions(target);if(!silent)console.info('[versions] 云端快照已保存',target.id,snapshot.id);return snapshot
 }
 const histories=readLocalVersionHistory(),key=versionHistoryKey(target),list=Array.isArray(histories[key])?histories[key]:[];list.unshift(snapshot);histories[key]=list.slice(0,MAX_MAP_VERSIONS);localStorage.setItem(VERSION_HISTORY_KEY,JSON.stringify(histories));if(!silent)console.info('[versions] 本地快照已保存',target.id,snapshot.id);return snapshot
}
async function pruneCloudVersions(target){const{data:rows,error}=await cloud.from('mindmap_versions').select('id').eq('mindmap_id',target.id).eq('owner_id',target.cloudOwnerId).order('created_at',{ascending:false});if(error)throw error;const expired=(rows||[]).slice(MAX_MAP_VERSIONS).map(row=>row.id);if(expired.length){const{error:deleteError}=await cloud.from('mindmap_versions').delete().eq('mindmap_id',target.id).eq('owner_id',target.cloudOwnerId).in('id',expired);if(deleteError)throw deleteError}}
