function versionActionButton(label,action,className=''){const button=document.createElement('button');button.type='button';button.className=`secondary version-history-action ${className}`.trim();button.dataset.versionAction=action;button.textContent=label;return button}
function renderVersionHistoryList(snapshots){const list=$('#versionHistoryList'),empty=$('#versionHistoryEmpty');list.replaceChildren();empty.hidden=snapshots.length>0;for(const version of snapshots){const card=document.createElement('article');card.className='version-history-item'+(version.id===selectedVersionId?' is-selected':'');card.dataset.versionId=version.id;const preview=document.createElement('button');preview.className='version-history-preview';preview.type='button';preview.dataset.versionAction='select';preview.setAttribute('aria-label','选择版本 '+(version.versionName||'历史版本'));if(version.thumbnail){const image=document.createElement('img');image.src=version.thumbnail;image.alt='';preview.append(image)}else{const placeholder=document.createElement('span');placeholder.className='version-history-placeholder';placeholder.textContent='◇';preview.append(placeholder)}const details=document.createElement('div');details.className='version-history-details';const name=document.createElement('strong');name.className='version-history-name';name.textContent=version.versionName||'未命名版本';const time=document.createElement('time');time.className='version-history-time';time.dateTime=version.createdAt||'';time.textContent=versionHistoryFormatDate(version.createdAt);details.append(name,time);const actions=document.createElement('div');actions.className='version-history-actions';actions.append(versionActionButton('恢复到此版本','restore','primary'),versionActionButton('重命名','rename'),versionActionButton('删除','delete','danger'));card.append(preview,details,actions);list.append(card)}}
