function initVersionHistory(){const button=$('#versionHistoryBtn'),modal=$('#versionHistoryModal'),list=$('#versionHistoryList');if(!button||!modal||!list)return;button.addEventListener('click',openVersionHistory);$('#closeVersionHistory').addEventListener('click',closeVersionHistory);modal.addEventListener('click',event=>{if(event.target===modal)closeVersionHistory()});list.addEventListener('click',event=>{const card=event.target.closest('.version-history-item'),control=event.target.closest('[data-version-action]');if(!card)return;const id=card.dataset.versionId,action=control?.dataset.versionAction;if(action==='restore')restoreVersionSnapshot(id);else if(action==='rename')renameVersionSnapshot(id);else if(action==='delete')deleteVersionSnapshot(id);else{selectedVersionId=id;list.querySelectorAll('.version-history-item').forEach(item=>item.classList.toggle('is-selected',item===card))}});document.addEventListener('keydown',event=>{if(!modal.hidden&&event.key==='Escape')closeVersionHistory()})}initVersionHistory();
