function validateImportedMap(value){if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('JSON 顶层必须是导图对象');if(typeof value.title!=='string'||!value.title.trim())throw new Error('缺少有效的导图标题');if(!Array.isArray(value.nodes)||!value.nodes.length)throw new Error('缺少节点数组');if(value.nodes.length>10000)throw new Error('节点数量超过 10000，无法安全导入');const ids=new Set();for(const node of value.nodes){if(!node||typeof node!=='object'||Array.isArray(node)||typeof node.id!=='string'||!node.id||typeof node.text!=='string'||!(node.parent===null||typeof node.parent==='string'))throw new Error('节点必须包含 id、text 和有效的 parent 字段');if(ids.has(node.id))throw new Error('节点 id 重复');ids.add(node.id);if(node.order!=null&&!Number.isFinite(node.order))throw new Error('节点排序字段 order 无效');if(node.fillColor!=null&&(typeof node.fillColor!=='string'||!/^#[0-9a-f]{6}$/i.test(node.fillColor)))throw new Error('节点背景色格式无效');if(node.fillColorSource!=null&&!['auto','custom'].includes(node.fillColorSource))throw new Error('节点颜色来源标记无效');if(node.textColor!=null&&(typeof node.textColor!=='string'||!/^#[0-9a-f]{6}$/i.test(node.textColor)))throw new Error('节点文字颜色格式无效');if(node.fontSize!=null&&(!Number.isFinite(node.fontSize)||node.fontSize<8||node.fontSize>32))throw new Error('节点字号超出有效范围');if(node.fontFamily!=null&&!['sans','serif','mono'].includes(node.fontFamily))throw new Error('节点字体类型无效');if(node.bold!=null&&typeof node.bold!=='boolean')throw new Error('节点加粗标记无效');if(node.italic!=null&&typeof node.italic!=='boolean')throw new Error('节点斜体标记无效');if(node.note!=null&&typeof node.note!=='string')throw new Error('节点备注必须是文本')}const roots=value.nodes.filter(node=>node.parent===null);if(roots.length!==1)throw new Error('导图必须且只能有一个根节点');const children=new Map();for(const node of value.nodes){if(node.parent!==null&&!ids.has(node.parent))throw new Error('存在找不到父节点的孤立节点');if(!children.has(node.parent))children.set(node.parent,[]);children.get(node.parent).push(node)}const visited=new Set(),visiting=new Set();function visit(node){if(visiting.has(node.id))throw new Error('节点层级存在循环引用');if(visited.has(node.id))return;visiting.add(node.id);for(const child of children.get(node.id)||[])visit(child);visiting.delete(node.id);visited.add(node.id)}visit(roots[0]);if(visited.size!==value.nodes.length)throw new Error('存在未连接到根节点的节点');return{title:value.title.trim(),theme:THEME_PRESETS[value.theme]?value.theme:"default",nodes:value.nodes.map(node=>({...node}))}}
