function importedNodeText(value){if(typeof value==='string'||typeof value==='number')return String(value).trim();if(!value||typeof value!=='object')return'';for(const key of ['text','title','name','label','topic','content','value']){const item=value[key];if(typeof item==='string'||typeof item==='number'){const text=String(item).trim();if(text)return text}if(item&&typeof item==='object'&&!Array.isArray(item)){const text=importedNodeText(item);if(text)return text}}if(value.data&&typeof value.data==='object')return importedNodeText(value.data);return''}
