function shareEntries(query=''){if(!ownerId)return[];const entries=cloudFolders.filter(x=>x.isShared).map(item=>({kind:'folder',storage:'cloud',id:item.id,item})).concat(cloudMaps.filter(x=>x.isShared).map(item=>({kind:'map',storage:'cloud',id:item.id,item})));const filtered=entries.filter(entry=>matchesSearch(entry.item,query));return filtered.sort((a,b)=>{const ka=shareKey(a.kind,a.id),kb=shareKey(b.kind,b.id),oa=shareOrder[ka],ob=shareOrder[kb];if(Number.isFinite(oa)&&Number.isFinite(ob)&&oa!==ob)return oa-ob;if(Number.isFinite(oa)!==Number.isFinite(ob))return Number.isFinite(oa)?-1:1;return new Date(shareTimestamp(b)||0)-new Date(shareTimestamp(a)||0)})}
