function shareChangesForEntry(entry,desiredShared,allowExport){const changes=[];const add=(kind,item,shared,exportAllowed)=>{const before={is_shared:!!item.isShared,share_id:item.shareId||null,allow_export:!!item.allowExport},after=shared?{is_shared:true,share_id:item.isShared&&item.shareId?item.shareId:newShareId(),allow_export:!!exportAllowed}:{is_shared:false,share_id:null,allow_export:false};if(JSON.stringify(before)!==JSON.stringify(after))changes.push({kind,id:item.id,before,after})};const item=shareItem(entry);if(!item)throw new Error('分享项目已不存在');add(entry.kind,item,desiredShared,allowExport);if(entry.kind==='folder'){const folderIds=folderDescendantIds(cloudFolders,entry.id);for(const folder of cloudFolders)if(folderIds.has(folder.id)&&folder.id!==entry.id)add('folder',folder,desiredShared,allowExport);for(const mapItem of cloudMaps)if(folderIds.has(mapItem.folderId))add('map',mapItem,desiredShared,allowExport)}return changes}
function setShareMemory(change,state,at=null){const item=shareCollection(change.kind).find(value=>value.id===change.id);if(item){item.isShared=!!state.is_shared;item.shareId=state.share_id||null;item.allowExport=!!state.allow_export;item.shareOpenedAt=state.is_shared?(at||shareOpenedAt[shareKey(change.kind,change.id)]||shareIdTimestamp(state.share_id)||new Date().toISOString()):null;if(state.is_shared&&!shareOpenedAt[shareKey(change.kind,change.id)])shareOpenedAt[shareKey(change.kind,change.id)]=item.shareOpenedAt;if(!state.is_shared)delete shareOpenedAt[shareKey(change.kind,change.id)]}if(change.kind==='map'){const local=data.maps.find(value=>value.id===change.id&&value.cloudOwnerId===ownerId);if(local&&item){local.isShared=item.isShared;local.shareId=item.shareId;local.allowExport=item.allowExport;local.shareOpenedAt=item.shareOpenedAt}}}
function shareTable(kind){return kind==='folder'?'folders':'mindmaps'}
async function persistShareChanges(changes,{record=true,quiet=false}={}){if(!changes.length)return true;if(!cloud||!ownerId)throw new Error('请先登录云端账号');const lockKeys=changes.map(change=>shareKey(change.kind,change.id));if(lockKeys.some(key=>shareRequestLocks.has(key)))return false;lockKeys.forEach(key=>shareRequestLocks.add(key));renderLibrary();refreshEditorSidebar();refreshShareDialog();const completed=[];try{for(const change of changes)if(change.kind==='map'&&!await flushCloudSave(change.id,true))throw new Error('脑图尚有云端修改未保存，分享设置未更改');for(const change of changes){const table=shareTable(change.kind),body=change.after,where={id:change.id,owner_id:ownerId};console.debug('[share] 更新分享配置',{table,body,where});const{data:updated,error}=await cloud.from(table).update(body).eq('id',where.id).eq('owner_id',where.owner_id).select('id').maybeSingle();if(error)throw error;if(!updated)throw new Error('没有更新记录；请检查 Supabase 分享迁移与 RLS UPDATE 策略');completed.push(change)}for(const change of changes){const key=shareKey(change.kind,change.id),wasShared=!!change.before.is_shared;setShareMemory(change,change.after,change.after.is_shared?(wasShared?shareOpenedAt[key]||shareItem({kind:change.kind,id:change.id})?.shareOpenedAt:new Date().toISOString()):null)}try{localStorage.setItem(SHARE_OPENED_KEY,JSON.stringify(shareOpenedAt))}catch(error){console.warn('[share] 本地分享时间缓存失败',error)}if(record){shareUndo.push({changes:changes.map(change=>({...change,before:{...change.before},after:{...change.after}}))});shareRedo=[]}localStorage.setItem(STORAGE,JSON.stringify(data));renderLibrary();refreshEditorSidebar();syncCanvasShareButton();refreshShareDialog();if(!quiet){if(changes.some(change=>!change.before.is_shared&&change.after.is_shared))toast('分享已开启，链接已复制到剪贴板');else if(changes.some(change=>change.before.is_shared&&!change.after.is_shared))toast('分享已关闭，分享链接失效');else toast('分享设置已更新')}return true}catch(error){console.error('[share] 配置更新失败',error,{completed:completed.map(change=>({kind:change.kind,id:change.id}))});for(const change of completed.reverse()){const{error:rollbackError}=await cloud.from(shareTable(change.kind)).update(change.before).eq('id',change.id).eq('owner_id',ownerId);if(rollbackError)console.error('[share] 失败后回滚未完成',rollbackError,change)}throw error}finally{lockKeys.forEach(key=>shareRequestLocks.delete(key));renderLibrary();refreshEditorSidebar();refreshShareDialog()}}
async function changeShare(entry,shared,allowExport){if(entry.storage!=='cloud'){toast('本地文件无法对外分享，请先保存到云端');return false}if(!ownerId||!cloud)return toast('请先登录云端账号');const lock=shareKey(entry.kind,entry.id);if(shareRequestLocks.has(lock))return false;try{const existing=shareItem(entry),effectiveExport=allowExport===undefined?(existing?.isShared?!!existing.allowExport:!!userSettings.share_allow_export_default):!!allowExport,changes=shareChangesForEntry(entry,shared,effectiveExport);if(!changes.length){if(shared)await copyShareLink(shareItem(entry)?.shareId);return true}const ok=await persistShareChanges(changes);if(ok&&shared&&changes.some(change=>!change.before.is_shared&&change.after.is_shared))await copyShareLink(shareItem(entry)?.shareId,false);return ok}catch(error){const message=error?.message||error?.details||'网络或服务异常';toast('分享设置失败：'+message);return false}}
function shareUrl(id){return new URL('/share/'+encodeURIComponent(id),location.origin).href}
