function refreshShareDialog(){const modal=$('#shareModal');if(!modal||modal.hidden||!shareDialogEntry)return;const item=shareItem(shareDialogEntry);if(!item)return;$('#shareEnabledInput').checked=!!item.isShared;$('#shareExportInput').checked=item.isShared?!!item.allowExport:!!userSettings.share_allow_export_default;$('#shareExportInput').disabled=!item.isShared||shareRequestLocks.has(shareKey(shareDialogEntry.kind,shareDialogEntry.id));$('#shareEnabledInput').disabled=shareRequestLocks.has(shareKey(shareDialogEntry.kind,shareDialogEntry.id));$('#shareLinkSection').hidden=!item.isShared||!item.shareId;$('#shareUrlInput').value=item.shareId?shareUrl(item.shareId):'';$('#shareDialogTitle').textContent=(shareDialogEntry.kind==='folder'?'文件夹分享 · ':'脑图分享 · ')+(item.title||'未命名');$('#shareDialogStatus').textContent=item.isShared?'拥有链接的人可以只读预览'+(item.allowExport?'，并允许导出。':'。'):'分享已关闭。'}
function openShareDialog(entry){if(entry.storage!=='cloud')return toast('本地文件无法对外分享，请先保存到云端');if(!ownerId||!cloud)return toast('请先登录云端账号');shareDialogEntry={...entry};refreshShareDialog();$('#shareModal').hidden=false;$('#closeShareDialog').focus()}
