function syncCanvasShareButton(){const button=$('#canvasShareBtn'),target=map();if(!button)return;const cloudMap=target?.cloudOwnerId?cloudMaps.find(item=>item.id===target.id):null,shared=!!cloudMap?.isShared;button.classList.toggle('is-shared',shared);button.setAttribute('aria-pressed',String(shared));button.title=target?.cloudOwnerId?(shared?'管理当前脑图分享':'分享当前脑图'):'本地文件无法对外分享';button.disabled=!target;button.querySelector('[aria-hidden="true"]')?.replaceChildren(document.createTextNode(shared?'↗':'⇧'));const label=button.querySelector('span:last-child');if(label)label.textContent=shared?'已分享':'分享'}
