function undoShareChange(){if(!shareUndo.length)return false;void shareHistory('undo');return true}
function redoShareChange(){if(!shareRedo.length)return false;void shareHistory('redo');return true}
async function shareHistory(direction){const undo=direction==='undo',source=undo?shareUndo:shareRedo,dest=undo?shareRedo:shareUndo;if(!source.length)return false;const change=source.pop();try{const ok=await applyShareHistory(change,!undo);if(!ok)throw new Error('分享设置仍在处理中');dest.push(change);return true}catch(error){source.push(change);toast('分享操作'+(undo?'撤销':'重做')+'失败：'+(error?.message||'请重试'));return false}}
function outlineShareTree(nodes,rootId){const byId=new Map(nodes.map(node=>[node.id,node])),renderBranch=(node,depth)=>{const children=orderedChildren(nodes,node.id),li=document.createElement('li'),label=document.createElement('span');label.textContent=node.text||'未命名节点';li.append(label);if(node.note){const note=document.createElement('div');note.className='public-share-note';note.textContent=node.note;li.append(note)}for(const block of (node.content||[]).slice(1)){if(block.type==='image'){const image=document.createElement('img');image.src=block.src;image.alt=block.alt||'';image.loading='lazy';image.className='public-share-image';li.append(image)}else if(block.type==='link'){const link=document.createElement('a');link.href=block.href;link.target='_blank';link.rel='noopener noreferrer';link.textContent=block.text;li.append(link)}else if(block.type==='math'){const formula=document.createElement('code');formula.className='public-share-formula';formula.textContent=block.latex;li.append(formula)}}if(children.length){const ul=document.createElement('ul');for(const child of children)ul.append(renderBranch(child,depth+1));li.append(ul)}return li};const root=byId.get(rootId)||nodes.find(node=>node.parent==null);if(!root)return document.createElement('div');const fragment=document.createDocumentFragment(),heading=document.createElement('h2');heading.textContent=root.text||'未命名导图';fragment.append(heading);const children=orderedChildren(nodes,root.id);if(children.length){const ul=document.createElement('ul');for(const child of children)ul.append(renderBranch(child,1));fragment.append(ul)}return fragment}
function publicSupabaseConfig(){const supplied=window.SHINIAN_PUBLIC_SUPABASE||{},local=cloudConfig()||{};return{url:String(supplied.url||local.url||''),key:String(supplied.anonKey||supplied.key||local.key||'')}}
async function loadPublicShare(){const shareId=decodeURIComponent(location.pathname.split('/').filter(Boolean).at(-1)||''),title=$('#publicShareTitle'),description=$('#publicShareDescription'),tree=$('#publicShareTree'),status=$('#publicShareStatus'),exportButton=$('#publicShareExport');tree.replaceChildren();exportButton.hidden=true;if(!shareId){title.textContent='该分享链接不存在或已失效';description.textContent='';return}const config=publicSupabaseConfig();if(!config.url||!config.key||!window.supabase?.createClient){title.textContent='分享暂时无法加载';description.textContent='网站尚未配置公开 Supabase Project URL 与 anon key。';status.textContent='站点管理员需在 supabase-public-config.js 中配置公开 anon key。';return}const client=window.supabase.createClient(config.url,config.key,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});let row,kind;try{let result=await client.from('mindmaps').select('*').eq('share_id',shareId).eq('is_shared',true).maybeSingle();if(result.error)throw result.error;if(result.data){row=result.data;kind='map'}else{result=await client.from('folders').select('*').eq('share_id',shareId).eq('is_shared',true).maybeSingle();if(result.error)throw result.error;row=result.data;kind='folder'}}catch(error){console.error('[share-public] 查询分享失败',error);title.textContent='分享加载失败';description.textContent='请稍后重试，或联系分享者。';status.textContent=error.message||'Supabase 请求失败';return}if(!row){title.textContent='该分享链接不存在或已失效';description.textContent='';status.textContent='';return}title.textContent=row.title||'未命名分享';description.textContent=kind==='folder'?'文件夹只读预览':'思维导图只读预览';const allow=!!row.allow_export;exportButton.hidden=!allow;let exportPayload;if(kind==='map'){const item=mapFromCloudRow(row,row.owner_id);tree.append(outlineShareTree(item.nodes,rootNodeId(item)));exportPayload={kind:'mindmap',title:item.title,theme:item.theme,nodes:item.nodes}}else{const[foldersResult,mapsResult]=await Promise.all([client.from('folders').select('*').eq('owner_id',row.owner_id).eq('is_shared',true),client.from('mindmaps').select('*').eq('owner_id',row.owner_id).eq('is_shared',true)]);if(foldersResult.error||mapsResult.error){console.error('[share-public] 文件夹内容查询失败',foldersResult.error||mapsResult.error);status.textContent='文件夹内容加载失败';return}const folderRows=foldersResult.data||[],mapRows=mapsResult.data||[],ids=folderDescendantIds(folderRows.map(value=>({id:value.id,parentId:value.parent_id||null})),row.id);ids.add(row.id);const sections=[];for(const child of folderRows.filter(value=>ids.has(value.id)).sort((a,b)=>String(a.title).localeCompare(String(b.title),'zh-CN'))){const h=document.createElement('h2');h.textContent='📁 '+child.title;tree.append(h);sections.push({kind:'folder',id:child.id,title:child.title})}for(const mapRow of mapRows.filter(value=>ids.has(value.folder_id))){const item=mapFromCloudRow(mapRow,row.owner_id),section=document.createElement('section'),h=document.createElement('h2');h.textContent='🧠 '+(item.title||'未命名脑图');section.append(h,outlineShareTree(item.nodes,rootNodeId(item)));tree.append(section);sections.push({kind:'mindmap',title:item.title,theme:item.theme,nodes:item.nodes})}exportPayload={kind:'folder',title:row.title,folders:sections.filter(value=>value.kind==='folder'),maps:sections.filter(value=>value.kind==='mindmap')}}if(allow)exportButton.onclick=()=>downloadBlob(new Blob([JSON.stringify(exportPayload,null,2)],{type:'application/json'}),(row.title||'分享内容')+'.json');status.textContent='此页面为只读公开预览。'}
function initShareUi(){$('#shareEnabledInput').addEventListener('change',()=>{if(!shareDialogEntry)return;const checked=$('#shareEnabledInput').checked,old=shareItem(shareDialogEntry);$('#shareDialogStatus').textContent='正在保存分享设置…';void changeShare(shareDialogEntry,checked,checked?(old?.isShared?!!old.allowExport:$('#shareExportInput').checked):false).then(ok=>{if(!ok)refreshShareDialog()})});$('#shareExportInput').addEventListener('change',()=>{if(!shareDialogEntry)return;const item=shareItem(shareDialogEntry);void changeShare(shareDialogEntry,true,$('#shareExportInput').checked).then(ok=>{if(!ok)refreshShareDialog()})});$('#copyShareLinkBtn').addEventListener('click',()=>void copyShareLink(shareItem(shareDialogEntry||{})?.shareId));$('#closeShareDialog').addEventListener('click',closeShareDialog);$('#cancelShareDialog').addEventListener('click',closeShareDialog);$('#shareModal').addEventListener('click',event=>{if(event.target.id==='shareModal')closeShareDialog()});$('#shareModal').addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();closeShareDialog()}});$('#canvasShareBtn').addEventListener('click',()=>{const target=map();if(!target)return;if(!target.cloudOwnerId)return toast('本地文件无法对外分享，请先保存到云端');openShareDialog({kind:'map',storage:'cloud',id:target.id})});if(currentView==='share'){document.body.classList.add('public-share-mode');$('#libraryView').hidden=true;$('#editorView').hidden=true;$('#shareView').hidden=false;void loadPublicShare()}else $('#shareView').hidden=true}
initShareUi();initGlobalSettings();
