for(const button of document.querySelectorAll('.global-nav-item[data-library-tab]'))button.addEventListener('click',()=>{libraryNav=button.dataset.libraryTab;libraryMode=libraryNav==='recent'?'recent':'folder';if(libraryNav==='home'){currentFolderId=null;currentLocalFolderId=null;saveLocalLibrary();saveFolderUi()}if(libraryNav==='cloud'||libraryNav==='recent'){currentFolderId=null;saveFolderUi()}renderLibrary()});$('#libraryTrashBtn').addEventListener('click',()=>{libraryNav=ownerId?'trash-cloud':'trash-local';renderLibrary()});$('#cloudRecycleEntry').addEventListener('click',()=>{libraryNav='trash-cloud';renderLibrary()});$('#localRecycleEntry').addEventListener('click',()=>{libraryNav='trash-local';renderLibrary()});
$('#canvasStarBtn').addEventListener('click',()=>{const target=map();if(!target)return;void changeFavorite({kind:'map',storage:target.cloudOwnerId?'cloud':'local',id:target.id},{canvasUndo:true}).catch(error=>{console.error('[favorite] 画布星标点击处理异常',error);toast('收藏操作失败：'+(error?.message||'请重试'))})});
document.addEventListener('keydown',event=>{if(currentView!=='library'||!(event.ctrlKey||event.metaKey)||event.altKey)return;const target=event.target instanceof Element?event.target:null;if(target?.matches('input,textarea,select,[contenteditable="true"]'))return;const key=event.key.toLowerCase();if(key==='z'&&!event.shiftKey&&shareUndo.length){event.preventDefault();undoShareChange();return}if((key==='y'||key==='z'&&event.shiftKey)&&shareRedo.length){event.preventDefault();redoShareChange();return}if(key==='z'&&!event.shiftKey&&favoriteUndo.length){event.preventDefault();const change=favoriteUndo.pop();void applyFavoriteHistory(change,false).then(ok=>{if(ok)favoriteRedo.push(change);else favoriteUndo.push(change)});return}if((key==='y'||key==='z'&&event.shiftKey)&&favoriteRedo.length){event.preventDefault();const change=favoriteRedo.pop();void applyFavoriteHistory(change,true).then(ok=>{if(ok)favoriteUndo.push(change);else favoriteRedo.push(change)})}});
let deferredPwaInstallPrompt=null;const pwaInstallButton=$('#installAppBtn');if(pwaInstallButton){const standalone=window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;if(standalone)pwaInstallButton.hidden=true;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredPwaInstallPrompt=event;pwaInstallButton.hidden=false});window.addEventListener('appinstalled',()=>{deferredPwaInstallPrompt=null;pwaInstallButton.hidden=true;toast('拾念已安装')});pwaInstallButton.addEventListener('click',async()=>{if(!deferredPwaInstallPrompt){toast('请使用浏览器菜单中的“安装应用”或“添加到主屏幕”');return}deferredPwaInstallPrompt.prompt();const choice=await deferredPwaInstallPrompt.userChoice;deferredPwaInstallPrompt=null;if(choice?.outcome==='accepted')pwaInstallButton.hidden=true})}
renderCanvasTabs();if(currentView==='editor'&&map()){render();syncCanvasFavoriteButton();syncCanvasShareButton();scheduleInitialCanvasLayout(map().id,!canvasTabStates.has(map().id))}else if(currentView==='library')renderLibrary()
