try{if(currentView!=='share'){let savedCloudConfig=cloudConfig();if(!savedCloudConfig){const published=window.SHINIAN_PUBLIC_SUPABASE||{},url=String(published.url||'').trim(),key=String(published.anonKey||published.key||'').trim();if(url&&key){savedCloudConfig={url,key,verified:false};localStorage.setItem(CLOUD_CONFIG,JSON.stringify(savedCloudConfig))}}updateCloudPanel();if(savedCloudConfig)connectCloud(savedCloudConfig)}}catch(error){console.error('[auth] 恢复云端登录状态失败',error);toast('恢复云端登录状态失败：'+(error?.message||'请检查连接配置'))}

